export const getAllArticles = () => articles
export const getArticle = (slug) => articles.find((a) => a.slug === slug)
export const getArticleCategories = () => {
  const map = new Map()
  articles.forEach((a) => map.set(a.category, (map.get(a.category) || 0) + 1))
  return [...map].map(([name, count]) => ({ name, slug: name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''), count }))
}
export const categorySlug = (c) => c.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
